CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS connected_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES users(id), provider text NOT NULL, account_ref text, secret_ref text NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(user_id,provider));
CREATE TABLE IF NOT EXISTS repositories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text, owner text NOT NULL, name text NOT NULL, default_branch text, head_sha text, metadata jsonb NOT NULL DEFAULT '{}', updated_at timestamptz DEFAULT now(), UNIQUE(owner,name));
CREATE TABLE IF NOT EXISTS repository_indexes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repository_id uuid REFERENCES repositories(id), commit_sha text NOT NULL, status text NOT NULL, file_count int DEFAULT 0, completed_at timestamptz, evidence jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS repository_files (repository_id uuid REFERENCES repositories(id), commit_sha text NOT NULL, path text NOT NULL, sha text, language text, size_bytes int, content_hash text, embedding vector(1536), PRIMARY KEY(repository_id,commit_sha,path));
CREATE TABLE IF NOT EXISTS repository_analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repository_id uuid, commit_sha text, analysis_type text NOT NULL, result jsonb NOT NULL, evidence jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks (id text PRIMARY KEY, user_id text, repository_id uuid, state text NOT NULL, input_json jsonb NOT NULL, idempotency_key text UNIQUE, approval_status text DEFAULT 'NOT_REQUIRED', final_outcome jsonb, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS task_dependencies (task_id text REFERENCES tasks(id), depends_on text REFERENCES tasks(id), PRIMARY KEY(task_id,depends_on));
CREATE TABLE IF NOT EXISTS execution_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text REFERENCES tasks(id), plan jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_executions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text, agent_name text NOT NULL, status text NOT NULL, input_json jsonb, output_json jsonb, evidence jsonb, confidence numeric, started_at timestamptz DEFAULT now(), finished_at timestamptz);
CREATE TABLE IF NOT EXISTS agent_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text, agent_name text, message_json jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS code_changes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text, worker_run_id text, branch text, diff_ref text, result jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS test_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text, worker_run_id text, result jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS security_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text, severity text, finding jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS pull_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text, owner text, repo text, number int, url text, status text, metadata jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS opportunities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repository text, source_url text NOT NULL, issue_number int, score numeric, evidence jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS research_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id text, url text NOT NULL, title text, retrieved_at timestamptz DEFAULT now(), content_hash text, claims jsonb);
CREATE TABLE IF NOT EXISTS project_memory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), repository_id uuid, scope text, key text, value jsonb, commit_sha text, evidence jsonb, confidence numeric, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id text UNIQUE, workflow_name text, status text, input_json jsonb, output_json jsonb, error_json jsonb, attempts int DEFAULT 0, next_retry_at timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text, task_id text, action text NOT NULL, metadata jsonb, created_at timestamptz DEFAULT now());
